#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""goAmnezia pro — служба страниц подключения (lib/pages.sh, docs/CLIENTS.md §6–§8).

Зачем она есть. Человек получает не файл, а страницу: свои ключи (файлом,
QR, ссылкой в приложение), приложения под своё устройство (ссылки, QR) и
«запросить копию приложения на наш сервер». Страница живёт часы, дни или
бессрочно, поэтому отдаёт её не одноразовый процесс (как у временной ссылки,
lib/share_server.py), а постоянная служба goamnezia-pages за nginx:
    nginx  location ~ "^/p-[A-Za-z0-9_-]{43}(/.*)?$"  →  127.0.0.1:1987 (этот процесс)
Секрет — 43 символа base64url в пути: путь И ЕСТЬ ключ, отдельной авторизации
нет (как у раздач и у адресов агентов).

Что здесь важнее красоты (docs/CLIENTS.md §6–§7):
  • ключи НЕ хранятся в службе: их каждый раз отдаёт мост
    `install.sh --action=user-key --json … --format=all` (кеш до 60 с, сброс
    по mtime users.json / config.json) — за дни жизни страницы ключ могли
    перевыпустить, а Endpoint сменить;
  • в первом HTML ключей НЕТ: ссылку открывают не только люди — роботы превью
    мессенджеров (Telegram, VK, Max) и проверялки почты забирают страницу сами,
    и полный приватный ключ уезжал к ним вместе с разметкой (SEC-G2). И сама
    страница ключей не просит: сканер ссылок с JavaScript отрисовывал её, получал
    conf и vpn://, а визит засчитывался (SEC50-05). Ключи (conf и vpn://) отдаёт
    POST keys.json с одноразовым значением, выданным при отрисовке страницы, и
    app.js шлёт его только после действия человека — тапа, клика или клавиши
    (кнопка «Показать ключ»); до него у ключей нет ни кнопок, ни ссылок на файл и
    QR. Визит считается там же — открытие без действия визитом не считается.
    Файл .conf и QR ключа — тоже только после него (SEC50-10): адреса key/… и
    qr/key/… без токена ?g=, который выдаёт тот же POST keys.json, — 404, и
    сканер, знающий адрес страницы, не заберёт файл ключа по предсказуемому имени;
  • ключ, выданный в приложении Amnezia до подхвата (у пира has_key: false —
    на сервере только открытая часть), страница не показывает, а объясняет
    человеку, что он у него уже есть; файлов и QR по такому профилю нет (404);
  • удалённый пользователь (и тёзка, заведённый после удаления), истёкшая или
    отозванная страница → 404 байт в байт как у nginx: секрет ничего не
    подтверждает. Снаружи 404 службы nginx подменяет своим (error_page 404 →
    @ga_pages_down в lib/website.sh): заголовки у него — те же, что у 404 сайта
    (SEC-G4). Выключенный пользователь — не 404: страница (200) «Доступ
    приостановлен» с причиной (выключил администратор, кончился трафик или
    срок) и что сделать (написать тому, кто прислал ссылку; приложение не
    удалять), без ключей; файлы и QR ключей у него — 404;
  • мост (install.sh от root) — дорогой ресурс: не больше BRIDGE_PARALLEL
    вызовов на службу, один вызов на пользователя за раз, а лишнему запросу —
    быстрый 503 «попробуйте ещё раз», а не очередь из процессов bash (SEC-G1);
  • промахи по секрету считаются по адресу клиента с баном (10 за 5 минут →
    15 минут молчания, тоже 404) — приём из lib/share_server.py. Заголовки
    X-Real-IP / X-Forwarded-For принимаются ТОЛЬКО с петли: их ставит nginx,
    а с публичного адреса их мог бы прислать сам стучащийся;
  • ни одного внешнего ресурса на странице: CSP default-src 'none', скрипт —
    отдельным маршрутом app.js, картинки — свои QR; X-Robots-Tag noindex,
    Referrer-Policy no-referrer, Cache-Control no-store;
  • секрет не пишется ни в лог, ни в аудит: маскируется до p-*** (mask_path);
  • файлы зеркала отдаёт nginx: ответ службы — X-Accel-Redirect на внутреннюю
    локацию /_ga_mirror/, сама служба решает лишь, что и кому;
  • QR — qrencode (есть в продукте): только для ключей (PNG приходят от моста
    вместе с ключом) и для ссылок из каталога по номеру; произвольный текст в
    QR не принимается;
  • вид (0.5.0) — макет handoff/iteration3/Client.dc.html: 8 устройств с Apple TV, выбор приложения из
    каталога, ключи по профилям, зеркало, «приостановлен» (три причины), крупный список под пульт на
    телевизоре, RU/EN, тёмная тема по системе, телефон от 360 px. Без JavaScript — шапка, статус и одна
    заметка, RU/EN там — ссылки ?lang=ru|en (единственный параметр адреса, который служба читает).

Подписки (lib/subs.sh, docs/SUBSCRIPTION.md) — та же служба, свой маршрут и своя локация nginx:
    nginx  location ~ "^/s-[A-Za-z0-9_-]{43}/<суффикс из белого списка>$"  →  127.0.0.1:1987
Постоянная ссылка на человека: all.yaml (профиль mihomo со всеми линиями — awgkeys.mihomo_profile из .conf каждой
линии; mihomo.yaml — прежнее имя, тот же ответ), all.txt (ссылки amneziawg:// всех линий — подписка incy и AWG
Manager), awgNN.conf и awgNN.vpn по линиям, all.vpn.
В отличие от страницы ключи отдаются без действия человека — их забирают роутер и приложение; поэтому подписка
создаётся только по просьбе, выключенному, удалённому и тёзке отвечает 404 (клиент оставит прежний конфиг), роботам
превью — 404, промахи по секрету — в тот же бан, заборы считаются без адреса (state.json подписки, sub-fetch в аудит
раз в час).

Короткие ссылки подписки (lib/shortlinks.py, docs/SUBSCRIPTION.md §11) — тоже здесь:
    nginx  location ~ GA_SITE_SHORT_PATH_RE (lib/website.sh: 8–14 знаков, цифра и две буквы, обрамление
           копирования из мессенджера — «(КОД)», «КОД.», «*КОД*», «КОД…») — сначала файлы сайта (try_files), потом
           →  127.0.0.1:1987; «/.КОД» — локация GA_SITE_SHORT_DOT_RE снимает точки rewrite'ом (без 403 сайта)
Кодом служба считает только путь, где после нормализации 8 знаков алфавита, хотя бы одна цифра набрана цифрой и не
меньше двух букв (у кода тех и других не меньше двух): слова сайта (/download, /wp-admin), даты и номера
(/2024-10-01, /12345678) — обычный 404 без балла, тревоги и строки в журнале.
Работают только с 2FA через Telegram-бота: бот не настроен — 404. С адреса, которому код не доверен, браузеру —
страница подтверждения (число, таймер, опрос ?r=<запрос>, итог), приложению — 404; доверенному адресу — то же, что
полный адрес этого суффикса (тело, заголовки, учёт заборов; браузеру all.yaml — текстом). После «Вход подтверждён»
страница выдаёт этому устройству полную ссылку подписки (SHORT-03): POST /<КОД> {request, nonce} — номер этого
подтверждённого запроса и одноразовое значение её отрисовки, 15 минут после решения; сама никуда не переходит, а
«Показать содержимое» — тот же адрес с меткой ?go=<запрос>, по которой нового запроса в бот служба не создаёт.
Адрес — X-Real-IP, и только с 127.0.0.1. На вкладке
«Подписка» страницы — кнопка «Короткая ссылка» (POST short.json) и ↻ (POST short-replace.json, опрос
short-status.json) со своим одноразовым значением.

Только stdlib, Python ≥ 3.8: на сервере нет и не будет pip-зависимостей.

Запуск (его делает юнит goamnezia-pages.service из lib/pages.sh):
    python3 pages_server.py --dir /opt/goamnezia --bind 127.0.0.1 --port 1987
"""

import os
import re
import sys
import json
import time
import hmac
import fcntl
import contextlib
import errno
import hashlib
import signal
import base64
import socket
import calendar
import threading
import subprocess
import http.server
import socketserver
import urllib.parse
from collections import OrderedDict

# Профиль mihomo подписок собирается тем же кодом форматов, что у моста (lib/awgkeys.py, рядом с этим файлом): из
# .conf линии, который отдаёт user-key, — без второго пути к ключам. Нет модуля (рабочая копия старше) — страницы
# работают как прежде, а all.yaml (и mihomo.yaml) отвечает 404 со строкой в журнале.
_HERE = os.path.dirname(os.path.abspath(__file__))
if _HERE not in sys.path:
    sys.path.append(_HERE)
try:
    import awgkeys
except ImportError:                                # pragma: no cover — поставка без lib/awgkeys.py
    awgkeys = None
# Короткие ссылки подписки с 2FA через Telegram-бота (lib/shortlinks.py, docs/SUBSCRIPTION.md §11) — тот же модуль, что
# у моста. Нет его (рабочая копия старше) — коротких ссылок нет: /<КОД> отвечает 404, кнопки на странице нет.
try:
    import shortlinks
except ImportError:                                # pragma: no cover — поставка без lib/shortlinks.py
    shortlinks = None

# ── Пороги бана — те же, что у временной ссылки (lib/share_server.py) ────────
BAN_FAILURES = 10                 # неудач с одного IP…
BAN_WINDOW = 300.0                # …за 5 минут…
BAN_SECONDS = 900.0               # …→ 15 минут молчания (тоже 404, не 429)
FAILURE_TABLE_MAX = 4096          # потолок таблицы IP: сканер не раздует память
READ_TIMEOUT = 30                 # секунд на чтение запроса
MAX_REQUEST_LINE = 2048           # длиннее наших путей не бывает
MAX_POST_BODY = 4096              # тело POST нам не нужно вовсе
KEY_CACHE_TTL = 60.0              # ключи от моста живут в памяти не дольше минуты
BRIDGE_TIMEOUT = 120.0            # мост отвечает секунды; больше — что-то сломано
BRIDGE_PARALLEL = 3               # вызовов моста (install.sh от root) одновременно — не больше
# Сколько запрос ждёт свободного места у моста. Раньше ждал до BRIDGE_TIMEOUT (две минуты):
# шестьдесят запросов сразу держали шестьдесят потоков, а ответ «занят» ещё и ложился в кеш как
# «пользователя нет» — страница минуту отвечала 404. Теперь несколько секунд на сглаживание всплеска
# (вызов моста на малом сервере — секунда-две, страница из трёх профилей — четыре вызова подряд, и
# четыре человека, открывшие ссылки разом, должны дождаться, а не увидеть «занят»), дальше — 503 с
# Retry-After: человек обновит страницу, а процессы bash не копятся (SEC-G1).
BRIDGE_QUEUE_WAIT = 5.0
# Ответы моста, которые ничего не говорят о человеке: мост не запустился, не уложился в BRIDGE_TIMEOUT
# или ответил не JSON. В кеш они не кладутся — иначе минутный сбой превращался в минуту 404 на живой
# странице; повторный вызов всё равно идёт по одному на человека и в пределах BRIDGE_PARALLEL.
BRIDGE_TRANSIENT = ("transport",)
# Сколько ждать, пока закончится вызов моста по тому же человеку (один вызов на пользователя
# за раз): самый долгий вызов — BRIDGE_TIMEOUT, плюс запас на запуск процесса.
USER_WAIT = BRIDGE_TIMEOUT + 10.0
BUSY_RETRY_AFTER = 5              # секунд в Retry-After ответа 503
PAGES_RESCAN = 2.0                # каталог страниц перечитывается не чаще
VISIT_AUDIT_INTERVAL = 3600       # page-visit в аудит — раз в час на страницу
# Одноразовое значение для ключей (SEC50-05): выдаётся при отрисовке страницы и живёт сутки — вкладку могут не
# закрывать; таблица ограничена, чтобы частые открытия страницы не раздували память.
REVEAL_TTL = 86400.0
REVEAL_MAX = 4096
REVEAL_RE = re.compile(r"^[A-Za-z0-9_-]{32}$")
# Токен на файл и QR ключа (SEC50-10): его выдаёт POST keys.json вместе с ключами, живёт он час, а открытая страница
# продлевает его (POST keys.json с ним) раньше. Без токена key/<профиль>.conf и qr/key/… отвечают 404.
GRANT_TTL = 3600.0
GRANT_MAX = 4096
QR_CACHE_MAX = 256                # PNG ссылок в памяти
MIRROR_RETRY_AFTER = 3600         # после провала заявку принимаем снова не раньше
SEEN_FRESH = 600                  # «подключался N мин назад» зелёным — за последние 10 минут (тик квот — раз в 5 минут)

PATH_RE = re.compile(r"^/p-([A-Za-z0-9_-]{43})(/.*)?$")
SECRET_RE = re.compile(r"^[A-Za-z0-9_-]{43}$")
# ── Подписки (lib/subs.sh, docs/SUBSCRIPTION.md): /s-<секрет>/<суффикс> ──────
SUB_PATH_RE = re.compile(r"^/s-([A-Za-z0-9_-]{43})/([A-Za-z0-9._-]{1,32})$")
SUB_NAME_RE = re.compile(r"^[A-Za-z0-9_-]{1,32}$")
# Линия → суффикс адреса и порядок линий в профиле mihomo и в all.vpn (3.1 → 2.0 → 1.5 → 1.0, как у продукта).
LINE_TOKENS = {"1.0": "awg10", "1.5": "awg15", "2.0": "awg20", "3.1": "awg31"}
SUB_LINE_ORDER = ("3.1", "2.0", "1.5", "1.0")
# Суффикс → (формат, линия) — белый список, тот же, что в локации nginx (_ga_site_subs_block в lib/website.sh). Имя —
# <какие линии>.<формат> (каталог форматов, docs/SUBSCRIPTION.md): all — все линии, awg31 / awg20 / awg15 / awg10 — одна.
# all.yaml — профиль mihomo; mihomo.yaml — прежнее имя того же профиля (уже выдано людям), awgv15 / awgv2 / awgv3 —
# синонимы владельца для awg15 / awg20 / awg31: рабочие, но в списках нигде не показываются. Суффикс выбирает ЛИНИЮ, а
# не профиль. all.txt — подписка incy (docs.incy.cc, «Multiple AmneziaWG servers in one subscription») и AWG Manager: по
# строке amneziawg://<base64url .conf без «=»>#<имя> на линию.
SUB_SUFFIXES = {"all.yaml": ("mihomo", ""), "mihomo.yaml": ("mihomo", ""), "all.vpn": ("vpn", ""),
                "all.txt": ("txt", "")}
for _line, _token in LINE_TOKENS.items():
    for _fmt in ("conf", "vpn"):
        SUB_SUFFIXES["%s.%s" % (_token, _fmt)] = (_fmt, _line)
for _token, _line in (("awgv15", "1.5"), ("awgv2", "2.0"), ("awgv3", "3.1")):
    for _fmt in ("conf", "vpn"):
        SUB_SUFFIXES["%s.%s" % (_token, _fmt)] = (_fmt, _line)
SUBS_RESCAN = 2.0                 # каталог подписок перечитывается не чаще
# Подписка, которая обновляется сама (R-1 проверки 15.10): забор всех линий сразу приложением — не просмотр в браузере
# (в том числе по короткой ссылке), не разовое скачивание curl/wget и не ключ одной линии awgNN.*: тот после смены линии
# отвечает 404, и приложение остаётся со старым ключом. По этому счёту (auto_fetches в state.json) ядро решает, кому
# после смены параметров сказать «обновится сама» (ga_amn_s4_audience), а кому — «импортировать заново». all.vpn — не она:
# разовый импорт пула продуктом серии (goVLESS, Kaskad, goTelegram; docs/SUBSCRIPTION.md §2), сам не обновляется (N-1).
SUB_AUTO_SUFFIXES = ("all.yaml", "mihomo.yaml", "all.txt")
SUB_MANUAL_CLIENTS = ("browser", "curl", "wget")
# Вкладка «Подписка» страницы подключения (решения владельца 04.10.2026): все устройства «Статического ключа», с
# телевизорами — там главный путь — короткая ссылка (будет отдельно), а пока incy и WG Tunnel; приложениям, которым ключ
# вставляют из буфера (AmneziaVPN, AmneziaWG), каталог телевизоры не даёт (subscription.platforms). Порядок там же
# (app.js); тот же список — у клиентов в ответе моста (GA_SUBS_PLATFORMS в lib/subs.sh). Приложение «рекомендуем» по
# устройству — поле subscription.recommended каталога (на iPhone и телевизорах — incy: обновляется сам, разовое —
# после): первым в списке и выбранным. Адрес подписки — не в HTML, а POST sub.json с одноразовым значением страницы
# (своим, не ключей: page.id + SUB_NONCE), по первому нажатию «QR-код» или «Скопировать» — тот же порядок, что у ключей
# (SEC50-05).
SUB_PLATFORMS = ("ios", "android", "android_tv", "tvos", "windows", "macos", "linux", "router")
# Порядок приложений на вкладке: профиль mihomo, ссылки amneziawg:// (incy, AWG Manager), затем разовое — vpn:// и .conf
SUB_FORMAT_ORDER = {"mihomo": 0, "txt": 1, "vpn": 2, "conf": 3}
SUB_NONCE = "/sub"
FETCH_AUDIT_INTERVAL = 3600       # sub-fetch в аудит — раз в час на подписку
# Короткая ссылка: путь, который nginx пропускает к службе после файлов сайта — 8–14 знаков [0-9A-Za-z -] (пробел —
# %20, если человек набрал его вместо тире) в обрамлении копирования из мессенджера: точка и до 3 знаков в начале
# («(КОД)», «.КОД») и до 6 в конце («КОД.», «КОД…») — как локации nginx, набор shortlinks.FRAME (тест сверяет);
# кодом ли он, решает shortlinks.as_code. И своё одноразовое значение для кнопок «Короткая ссылка» и ↻ на вкладке
# «Подписка» (каждый ответ выдаёт следующее).
SHORT_FRAME = "\t !\"'(),.:;<>?[]_`{}~*+\u00a0\u00ab\u00bb\u2013\u2014\u2018\u2019\u201c\u201d\u201e\u2022\u2026"
SHORT_PATH_RE = re.compile(r"^/\.?[{0}]{{0,3}}[0-9A-Za-z -]{{8,14}}[{0}]{{0,6}}/?$".format(re.escape(SHORT_FRAME)))


def short_path(raw):
    """Путь короткой ссылки из строки запроса (без ?…, с раскодированными %XX — nginx сравнивает локацию с
    раскодированным путём) или "": не короткая ссылка."""
    path = urllib.parse.unquote(str(raw or "").split("?", 1)[0])
    return path if SHORT_PATH_RE.match(path) else ""
SHORT_NONCE = "/short"
SHORT_SWEEP = 5.0                 # раз в столько секунд истёкшие запросы подтверждения закрываются (событие боту)
SUB_UPDATE_HOURS = 12             # Profile-Update-Interval по умолчанию (subs.update_interval в config.json)
# Тело подписки — данные, а не страница: ничего не исполнять и не встраивать.
SUB_CSP = "default-src 'none'; frame-ancestors 'none'; sandbox"
# Семейство клиента по User-Agent — для учёта заборов: сам User-Agent не храним (в нём бывает модель телефона и
# версия системы), только слово. Порядок важен: Clash Verge и FlClash называют себя и «clash».
CLIENT_FAMILIES = (
    ("clash-verge", re.compile(r"clash[-_ ]?verge", re.I)),
    ("flclash", re.compile(r"flclash", re.I)),
    ("mihomo-party", re.compile(r"mihomo[-_. ]?party", re.I)),
    ("clash-meta", re.compile(r"clash[-_. ]?meta|clashmetaforandroid", re.I)),
    ("mihomo", re.compile(r"mihomo", re.I)),
    ("clash", re.compile(r"clash", re.I)),
    ("incy", re.compile(r"\bincy\b", re.I)),
    ("v2raytun", re.compile(r"v2raytun", re.I)),
    ("wg-tunnel", re.compile(r"wg[-_ ]?tunnel", re.I)),
    ("keenetic", re.compile(r"keenetic", re.I)),
    ("amnezia", re.compile(r"amnezia", re.I)),
    ("curl", re.compile(r"^curl/", re.I)),
    ("wget", re.compile(r"^wget", re.I)),
    ("browser", re.compile(r"^mozilla/", re.I)),
)
PAGE_ID_RE = re.compile(r"^p-[a-f0-9]{4,8}$")
PROFILE_RE = re.compile(r"^awg[1-9]$")
APP_RE = re.compile(r"^[a-z0-9-]{2,32}$")
PLATFORM_RE = re.compile(r"^(android|android_tv|windows|macos|linux)$")
FILE_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._+-]{0,127}$")
LINES = ("1.0", "1.5", "2.0", "3.1")
# Линейка по имени профиля — последний запасной путь для справки о подхваченном ключе, когда её нет ни у пира,
# ни в config.json (установка до миграции ga_migrate_profile_line). У awg1 это 1.0 или 1.5 — различить их можно
# только по параметрам, которых служба не разбирает, поэтому честнее «1.x».
PROFILE_LINE_GUESS = {"awg1": "1.x", "awg2": "2.0", "awg3": "3.1"}
# Порядок ключей на странице — 3.1 первым, затем 2.0 и 1.x, как в SSH и в мастере (NC-27): рекомендуемое на телефоне
# приложение AmneziaWG линию 3.1 читает (lib/clients.json), а по алфавиту первым шёл 2.0.
PROFILE_ORDER = {"awg3": 0, "awg2": 1, "awg1": 2}
# Порядок по линии ключа (AWG31-01): место профиля — только имя контейнера, 3.1 бывает и в awg2.
LINE_RANK = {"3.1": 0, "2.0": 1, "1.5": 2, "1.0": 3, "1.x": 4}


def ordered_profiles(profiles):
    """Профили страницы в порядке показа: 3.1 → 2.0 → 1.x, прочие — в конце."""
    return sorted(profiles, key=lambda p: (PROFILE_ORDER.get(p, 9), p))
# Поля профиля с самим приватным ключом: в HTML их нет, их отдаёт только POST keys.json (SEC-G2, SEC50-05).
KEY_FIELDS = ("conf", "vpn")
# Порядок вкладок страницы. tvos (Apple TV) — рядом с Android TV; сама страница на Apple TV не
# открывается (браузера там нет), её открывают на телефоне, поэтому по User-Agent эта вкладка не
# выбирается никогда (detect_device) — только нажатием.
PLATFORMS = ("ios", "android", "android_tv", "tvos", "windows", "macos", "linux", "router")
GIB = 1073741824                  # «ГБ» продукта — 1024³ (lib/users.sh, DEFECTS §4.9)
MIB = 1048576
MONTHS_EN = ("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")

# Роботы превью ссылок: мессенджер сам открывает адрес, как только ссылку вставили
# в чат. Им — пустая оболочка без ключей и без визита (ключ уехал бы на сервер
# мессенджера, а счётчик визитов врал бы владельцу). Только узнаваемые имена
# роботов: встроенные браузеры Telegram («Telegram-Android»), VK и Facebook (FBAN)
# — это живые люди, им ключи нужны. WhatsApp — только в начале строки: так
# начинается его робот, а не браузер.
PREVIEW_RE = re.compile(
    r"(telegrambot|vkshare|facebookexternalhit|facebot|slackbot|slack-imgproxy|discordbot|twitterbot|"
    r"linkedinbot|skypeuripreview|mail\.ru_bot|googlebot|bingbot|yandex[a-z]*bot|redditbot|pinterestbot|"
    r"embedly|iframely)|^whatsapp/", re.I)

# Тело 404 — байт в байт как у nginx по умолчанию: ответ на чужой путь не
# должен отличаться от ответа сайта на тот же путь.
NGINX_404 = (b"<html>\r\n<head><title>404 Not Found</title></head>\r\n<body>\r\n"
             b"<center><h1>404 Not Found</h1></center>\r\n<hr><center>nginx</center>\r\n"
             b"</body>\r\n</html>\r\n")

CSP = ("default-src 'none'; img-src 'self'; style-src 'self' 'unsafe-inline'; "
       "script-src 'self'; connect-src 'self'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'")

