# Приложение по умолчанию на телефонах — то, что есть в российских магазинах, с пометкой «рекомендуем» (NC-16). Сверено по
# пометкам ссылок каталога (lib/clients.json, checked 2026-09-25): на iPhone AmneziaVPN «скрыто в российском App Store»,
# а AmneziaWG («Есть в российском App Store») и DefaultVPN («форк AmneziaVPN для российского App Store») доступны —
# берём AmneziaWG: одно приложение на iPhone и Android, открытый код, шаги импорта есть в макете. У ссылок Google Play
# пометок о российском магазине нет ни у AmneziaWG, ни у AmneziaVPN — тогда, по правилу владельца, тоже AmneziaWG.
# Выбор с пометками каталога сверяет tests/test_pages_server.py. Страница рекомендует приложение, только если оно есть
# на вкладке и понимает все линейки ключей страницы (page_data → recommend).
RECOMMENDED = {"ios": "amneziawg", "android": "amneziawg"}

# Подписи вкладок устройств — в порядке PLATFORMS (сверяет tests/test_pages_dryrun.sh с каталогом и мостом).
